"use strict"

module.exports.defaultChar = "?"

module.exports.encode = function encode (str, encoding) {
  str = "" + (str || "")
  var codec = module.exports.getCodec(encoding)
  return codec.name + ":" + str + module.exports.defaultChar
}

module.exports.getCodec = function getCodec (encoding) {
  var enc = module.exports._canonicalize(encoding)
  return { name: enc }
}

module.exports._canonicalize = function (encoding) {
  return ("" + encoding).toLowerCase().replace(/[^0-9a-z]/g, "")
}

module.exports.toEncoding = module.exports.encode

// Members attached only from inside function bodies (iconv-lite's
// skipDecodeWarning / supportsStreams / encodeStream).
module.exports.decode = function decode (buf, enc) {
  if (typeof buf === "string") {
    if (!module.exports.skipDecodeWarning) {
      module.exports.warned = (module.exports.warned || 0) + 1
      module.exports.skipDecodeWarning = true
    }
    buf = "" + buf
  }
  return buf + ":" + enc
}

module.exports.enable = function enable (name) {
  if (module.exports.supports) { return }
  module.exports.makeStream = function makeStream (x) { return name + "/" + x }
  module.exports.supports = true
}

module.exports.use = function use (x) {
  module.exports.enable("s")
  return module.exports.makeStream(x)
}

module.exports.state = function state () {
  return String(module.exports.supports) + String(module.exports.skipDecodeWarning) + String(module.exports.warned)
}

// A diagnostic line on stderr: stdout is unaffected.
module.exports.noisy = function noisy () {
  console.trace('trace', 1)
  return 'noisy'
}
